def add(key,title,sid,point,span,original,text,cids=(),kind='regional-evidence',status='well-supported',lim='',method='',destination=None,local=False):
 rid='r8v-'+key;s=dict(sources[sid]);locator=s.pop('reviewLocator');known=span is not None
 time={'kind':'occurrence' if known else 'unplaced','start':span[0] if known else None,'end':span[1] if known else None,'approximate':True,'original':original,'method':method or 'Original source chronology as stated; no recalibration or numerical date inferred from query scope.','interpretation':'A dated evidence/context envelope, not proof of continuous residence, ownership, travel or activity in every intervening year.' if known else 'Chronological context retained without inventing a calendar window. This is not a dated settlement.'}
 precision='Rounded editorial locality/region anchor from the named geographic setting; not a measured excavation coordinate, cultural boundary or confidence polygon.'
 overlay={'kind':kind,'basis':'schematic','geometry':{'type':'Point','coordinates':point},'precision':precision,'provenance':'Source names this geographic setting. Numerical anchor is editorial map orientation, not supplied source geometry.'}
 if destination:
  overlay.update({'direction':'forward','geometry':{'type':'LineString','coordinates':[point,destination]},'precision':'Schematic source-to-recipient connection, not an observed itinerary, navigable path or proof of direct travel. Endpoints are rounded regional anchors.'})
 limitations=lim or 'Access limitations appear in the bibliography. Geographic anchors are approximate. No resident population, ancient language identity or exact transport itinerary is inferred.'
 r={'id':rid,'revision':1,'type':'event','title':title,'culture':{'id':'unknown','name':'Attribution as discussed in source','kind':'unknown','color':'#9babb5'},'location':None,'destination':None,'routeKind':'schematic','overlay':overlay,'time':time,'claims':[{'id':'source-reviewed','text':text,'status':status,'explanation':limitations,'support':[{'sourceId':sid,'locator':locator,'stance':'supports','note':s['access']}]}],'sources':[s],'review':{'summary':text,'limitations':limitations,'discussion':'Source-specific findings are separated from generated synthesis. Model components, sample quantities and archaeological cultures are not automatic population, ethnicity or language identifications.','provenance':'Round8 author-uploaded research lead reconciled against the original scholarly source identified here. Full original intake remains in the private archive.','reviewedAt':'2026-10-29','history':['2026-10-29: Added source-checked round8 synthesis with explicit access, dating and location limits.'],'relatedIds':[]}}
 r['culture']['name']='Unknown attribution'
 if kind=='language':r['linguistics']={'languages':[{'id':'arawakan','name':'Arawakan languages','family':'Arawakan'}],'claimId':'source-reviewed','scope':'Calibration methodology and assessed historical associations; not a reconstructed language territory.','uncertainty':'Conditional archaeological/linguistic model with accepted and rejected candidates. No ancient speech directly observed.'}
 new.append(r)
 for cid in cids:admissions[cid].append(rid)
 return rid
def c(group,*nums):return ['r8-'+group+'-'+str(n) for n in nums]

